#!/usr/bin/env bash
# =============================================================================
# AssetGuard AI: recreate the complete project, file by file.
#
#   bash build_project.sh [target_dir]        (default: ./assetguard-ai)
#
# Generated by deploy/make_build_script.py. Do not edit by hand; regenerate.
# Writes 77 files (55 source files as plain text, 22 data files
# gzip+base64), then verifies every file's SHA-256.
#
# Not included: .env (secrets), trained models and the vector index (the Docker
# build recreates them from the raw data). Next step: bash run_on_ec2.sh
# =============================================================================
set -euo pipefail

TARGET="${1:-./assetguard-ai}"
mkdir -p "$TARGET"
cd "$TARGET"
echo "Writing AssetGuard AI project into $(pwd)"

b64dec() { base64 -d 2>/dev/null || base64 -D; }

# ---- .dockerignore
cat > '.dockerignore' <<'__ASSETGUARD_EOF__'
.env
.env.*
!.env.example
**/__pycache__
**/*.pyc
**/.DS_Store
database/*.db
state/
.git
Dockerfile
docker-compose.yml
README.md
deploy/
__ASSETGUARD_EOF__

# ---- .env.example
cat > '.env.example' <<'__ASSETGUARD_EOF__'
GEMINI_API_KEY=your-gemini-api-key
GEMINI_MODEL=gemini-3.1-flash-lite
__ASSETGUARD_EOF__

# ---- .gitignore
cat > '.gitignore' <<'__ASSETGUARD_EOF__'
.env
__pycache__/
*.pyc
.DS_Store
database/*.db
__ASSETGUARD_EOF__

# ---- .streamlit/config.toml
mkdir -p ".streamlit"
cat > '.streamlit/config.toml' <<'__ASSETGUARD_EOF__'
# How the dashboard is served, and how it looks.
#
# Streamlit reads this file automatically when it is started from the Project
# folder, which is where you run:
#
#     python3 -m streamlit run run_dashboard.py

[server]
# The assessment container only exposes 8080 and 8081. 8081 is the REST service.
port = 8080
address = "0.0.0.0"
# headless = true: inside a container there is no browser to open.
headless = true
# ...and this stops it asking for an email address the first time, which would sit
# waiting for an answer and look as though the program had frozen.
showEmailPrompt = false

[browser]
gatherUsageStats = false

[client]
# Hide the developer menu. Nobody reviewing a work order needs "Rerun" or
# "Clear cache" in the corner of the screen.
toolbarMode = "minimal"

[theme]
base = "light"
primaryColor = "#0F4C81"
backgroundColor = "#FFFFFF"
secondaryBackgroundColor = "#F3F6FA"
textColor = "#1B2A38"
borderColor = "#DCE3EB"
dataframeHeaderBackgroundColor = "#EEF3F8"
baseRadius = "medium"
baseFontSize = 15
showWidgetBorder = true
showSidebarBorder = true
__ASSETGUARD_EOF__

# ---- Dockerfile
cat > 'Dockerfile' <<'__ASSETGUARD_EOF__'
FROM python:3.12-slim

ENV PYTHONDONTWRITEBYTECODE=1 \
    PYTHONUNBUFFERED=1 \
    PIP_NO_CACHE_DIR=1 \
    HF_HOME=/opt/hf \
    STATE_DIRECTORY=/app/state \
    ANONYMIZED_TELEMETRY=False

WORKDIR /app

RUN useradd --create-home --uid 1000 app && mkdir -p /app/state /opt/hf && chown app:app /app /app/state /opt/hf

COPY requirements.txt .
RUN pip install -r requirements.txt

# Bake the embedding model into the image so the container starts offline.
USER app
RUN python -c "from sentence_transformers import SentenceTransformer; SentenceTransformer('all-MiniLM-L6-v2')"
ENV HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1

COPY --chown=app:app --chmod=755 entrypoint.sh .
COPY --chown=app:app . .

# A source-only checkout (e.g. made by deploy/build_project.sh) ships the raw CSVs
# but no trained models or vector index: build them here. Seeded, so the models
# match output/model_metrics.json. Skipped when the artifacts are already present.
RUN if [ ! -f output/models/breakdown_model.pkl ] || [ ! -d database/chroma_store ]; then \
        python run_data_preparation.py \
        && python run_model_training.py \
        && python run_knowledge_indexing.py \
        && rm -f data/*.csv; \
    fi

VOLUME ["/app/state"]
EXPOSE 8080 8081

HEALTHCHECK --interval=30s --timeout=5s --start-period=90s --retries=3 \
    CMD python -c "import urllib.request; urllib.request.urlopen('http://localhost:8081/docs', timeout=4)" || exit 1

ENTRYPOINT ["./entrypoint.sh"]
__ASSETGUARD_EOF__

# ---- README.md
cat > 'README.md' <<'__ASSETGUARD_EOF__'
# AssetGuard AI: Docker build

A clean, runnable copy of `p1/Project` packaged as a single container that serves:

| Port | Service |
|------|---------|
| 8080 | Streamlit dashboard |
| 8081 | REST API (Swagger UI at `/docs`) |

The image contains the trained models (`output/models`), the manual knowledge index
(`database/chroma_store`), the manuals (`data/docs`), the live fleet
(`data/input/current_fleet.csv`), the cleaned technician notes, and the
`all-MiniLM-L6-v2` embedding model, so it needs no downloads at start-up.
The only outside service it calls is Gemini.

## Run

```bash
cp .env.example .env          # then put your real GEMINI_API_KEY in .env
docker compose up --build -d
docker compose logs -f        # wait for "Uvicorn running" and the Streamlit URL
```

Open http://localhost:8080 and sign in with one of the seeded accounts that
`run_database_setup.py` prints in the logs (they come from `SEED_USER_ACCOUNTS` in
`config/config.py`; demo use only).

Without compose:

```bash
docker build -t assetguard-ai .
docker run -d --name assetguard-ai --env-file .env \
  -p 8080:8080 -p 8081:8081 -v assetguard-state:/app/state assetguard-ai
```

## Data that persists

`assetguard.db` (users, work orders, reviews, chat history, LLM call log) and
`checkpoint.db` (paused LangGraph runs waiting for a supervisor) live in `/app/state`,
which is the `assetguard-state` volume. Each one is created on first start.
`docker compose down -v` wipes it back to a fresh install.

## Environment variables

| Variable | Default | Purpose |
|----------|---------|---------|
| `GEMINI_API_KEY` | (required) | Language model key; the container refuses to start without it |
| `GEMINI_MODEL` | `gemini-3.1-flash-lite` | Model name |
| `STATE_DIRECTORY` | `/app/state` in the image | Folder for the two SQLite files |
| `API_PORT` | `8081` | REST service port |
| `API_BASE_URL` | `http://localhost:8081` | Where the dashboard finds the API |

## How this differs from `p1/Project`

- Code is unchanged apart from `config/config.py`: `API_PORT`, `API_BASE_URL` and the
  SQLite folder (`STATE_DIRECTORY`) can now be set from the environment. The defaults
  are the original values, so a local run behaves the same.
- `.streamlit/config.toml` uses `headless = true`.
- `requirements.txt` is pinned to the versions the models were trained with.
- Not included: `.env`, the local databases, the raw and processed training CSVs (except
  `technician_notes_clean.csv`, which the API reads), `tests.py`, caches.
  To retrain, copy the raw CSVs into `data/` and run `run_data_preparation.py` and
  `run_model_training.py` in a full checkout.
__ASSETGUARD_EOF__

# ---- access/password_security.py
mkdir -p "access"
cat > 'access/password_security.py' <<'__ASSETGUARD_EOF__'
"""Turns passwords into safe stored values, checks typed passwords, and issues session tokens.

The only place a typed password is ever handled.
"""

import hashlib
import hmac
import secrets

from config import config


def create_password_salt():
    """A fresh random salt, written as lower-case hex."""
    return secrets.token_hex(config.PASSWORD_SALT_BYTES)


def create_password_hash(plain_password, password_salt):
    """PBKDF2 over the UTF-8 password with the salt's raw bytes, as lower-case hex."""
    derived = hashlib.pbkdf2_hmac(
        config.PASSWORD_HASH_ALGORITHM,
        plain_password.encode("utf-8"),
        bytes.fromhex(password_salt),
        config.PASSWORD_HASH_ROUNDS,
    )
    return derived.hex()


def verify_password_matches(plain_password, stored_hash, stored_salt):
    """Hash the typed password the same way and compare in constant time."""
    if not plain_password:
        return False
    candidate = create_password_hash(plain_password, stored_salt)
    return hmac.compare_digest(candidate, stored_hash)


def create_session_token():
    """A fresh unguessable session token, written as lower-case hex."""
    return secrets.token_hex(config.SESSION_TOKEN_BYTES)
__ASSETGUARD_EOF__

# ---- access/permissions.py
mkdir -p "access"
cat > 'access/permissions.py' <<'__ASSETGUARD_EOF__'
"""What a role may see (dashboard pages) and what it may do (service areas).

The page list is a convenience for the sidebar; the area check is the control
the service enforces on every request.
"""

from config import config


def resolve_pages_for_role(role_name):
    """The role's pages in sidebar order, as a fresh list; [] for an unknown role."""
    return list(config.ROLE_PAGE_ACCESS.get(role_name, []))


def check_role_may_open_area(role_name, area_name):
    """True only when config.ROLE_AREA_ACCESS lists this area for this role."""
    return area_name in config.ROLE_AREA_ACCESS.get(role_name, [])


def resolve_area_for_path(request_path, request_method):
    """The one area a request belongs to, or '' for a path no entry covers."""
    # Submitting a decision is the review area wherever it sits (Safety Rule 02).
    if request_method.upper() == "POST" and request_path.endswith(config.REVIEW_PATH_ENDING):
        return config.AREA_REVIEW
    for path_start, area_name in config.AREA_BY_PATH_START.items():
        if request_path.startswith(path_start):
            return area_name
    return ""
__ASSETGUARD_EOF__

# ---- agentic/agents.py
mkdir -p "agentic"
cat > 'agentic/agents.py' <<'__ASSETGUARD_EOF__'
"""The six agents, plus the shared machinery for one language model call.

Every agent is exactly one model call: facts arrive as arguments, a judgement in
words leaves as the return value. No agent can call a tool, fetch data, score
risk, set a priority, estimate a duration or search the manuals.
"""

import json
import os
import re
import time

from dotenv import load_dotenv
from google import genai
from google.genai import types

from config import config

load_dotenv(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), ".env"))

_api_key = os.getenv(config.GEMINI_API_KEY_VARIABLE, "").strip()
if not _api_key or _api_key.lower().startswith(("your", "test", "replace", "<")):
    raise RuntimeError(
        config.GEMINI_API_KEY_VARIABLE + " is missing or still a placeholder. Put a real Gemini "
        "API key in Project/.env before starting the service."
    )

# The SDK retries failed requests by itself unless told not to. One invocation
# must be exactly one call, so a failure surfaces instead of silently repeating.
_client = genai.Client(
    api_key=_api_key,
    http_options=types.HttpOptions(retry_options=types.HttpRetryOptions(attempts=1)),
)
_generation_settings = types.GenerateContentConfig(
    temperature=config.GEMINI_TEMPERATURE,
    max_output_tokens=config.GEMINI_MAX_OUTPUT_TOKENS,
    # Agents interpret facts they are given; they never reach out for more.
    automatic_function_calling=types.AutomaticFunctionCallingConfig(disable=True),
)

LABEL_DECORATION = r"^[\s\-\*#•>]*"
LIST_MARKER = re.compile(r"^\s*(?:\d+\s*[.):-]|[-*•#]+)\s*")
SECTION_LINE = re.compile(r"^[\s#*]*[A-Za-z][A-Za-z0-9 /&()'-]{0,40}\s*\**\s*:")

# Field labels each agent asks the model to use, and the dictionary key each becomes.
PLANNER_FIELDS = ["INVESTIGATION FOCUS", "ORDER OF CHECKS", "RATIONALE"]
CONDITION_FIELDS = ["CONDITION SUMMARY", "KEY SIGNALS", "URGENCY", "RECOMMENDATION"]
PROBLEM_FIELDS = ["LIKELY PROBLEM TYPE", "CONFIDENCE COMMENT", "SUPPORTING EVIDENCE"]
PROCEDURE_FIELDS = ["PROCEDURE REFERENCE", "PERMIT REQUIRED", "PARTS REQUIRED", "SAFETY NOTES"]
PROCEDURE_STEPS_LABEL = "KEY STEPS"
WRITER_FIELDS = ["JOB SUMMARY", "SCHEDULING NOTE"]
WRITER_STEPS_LABEL = "TASK STEPS"
FINALIZER_FIELDS = ["FINAL SUMMARY", "CHANGES APPLIED"]
FINALIZER_STEPS_LABEL = "TASK STEPS"

FORMAT_RULES = (
    "Answer using exactly the labelled lines below, in this order. Put each value on the "
    "same line as its label, keep it to one line, and write nothing before or after them."
)


def _field_key(label):
    return label.lower().replace(" ", "_")


def _keyed(parsed_fields):
    return {_field_key(label): value for label, value in parsed_fields.items()}


def _facts_block(facts):
    return json.dumps(facts, indent=2, default=str)


def call_language_model(prompt_text, agent_name):
    """Exactly one call to the configured model; returns the tidied reply and its cost."""
    started = time.perf_counter()
    response = _client.models.generate_content(
        model=config.GEMINI_MODEL_NAME, contents=prompt_text, config=_generation_settings)
    latency_milliseconds = int(round((time.perf_counter() - started) * 1000))
    response_text = (response.text or "").strip()
    return {
        "response_text": response_text,
        "call_record": {
            "agent_name": agent_name,
            "model_name": config.GEMINI_MODEL_NAME,
            "prompt_characters": len(prompt_text),
            "response_characters": len(response_text),
            "latency_milliseconds": latency_milliseconds,
        },
    }


def parse_labelled_response(response_text, field_labels):
    """{label: value} for each requested label; the latest occurrence wins, missing ones are ''."""
    parsed = {label: "" for label in field_labels}
    for line in response_text.splitlines():
        cleaned = re.sub(LABEL_DECORATION, "", line).replace("**", "")
        for label in field_labels:
            match = re.match(r"^\s*" + re.escape(label) + r"\s*:\s*(.*)$", cleaned, flags=re.IGNORECASE)
            if match:
                parsed[label] = match.group(1).strip()
    return parsed


def parse_numbered_steps(response_text, section_label):
    """The list items under section_label, without markers, stopping at the next labelled section."""
    lines = response_text.splitlines()
    heading = re.compile(r"^\s*" + re.escape(section_label) + r"\s*:?\s*(.*)$", flags=re.IGNORECASE)
    steps = []
    collecting = False
    for line in lines:
        cleaned = re.sub(LABEL_DECORATION, "", line).replace("**", "")
        if not collecting:
            match = heading.match(cleaned)
            if match:
                collecting = True
                if match.group(1).strip():
                    steps.append(LIST_MARKER.sub("", match.group(1)).strip())
            continue
        if not line.strip():
            continue
        if not LIST_MARKER.match(line) and SECTION_LINE.match(line):
            break
        step = LIST_MARKER.sub("", line).replace("**", "").strip()
        if step:
            steps.append(step)
    return steps


def _labelled_template(field_labels, steps_label=None, steps_after=None):
    lines = []
    for label in field_labels:
        lines.append(label + ": <one line>")
        if steps_label and label == steps_after:
            lines.append(steps_label + ":")
            lines.append("1. <step>")
            lines.append("2. <step>")
    if steps_label and steps_after is None:
        lines.append(steps_label + ":")
        lines.append("1. <step>")
        lines.append("2. <step>")
    return "\n".join(lines)


def work_planner_agent(machine_profile, request_text):
    """The supervising agent: decide what the specialists should look at, and in what order."""
    register_facts = {
        name: machine_profile.get(name)
        for name in ("machine_code", "machine_type", "factory_name", "production_line",
                     "importance", "usage_pattern", "machine_age_months")
    }
    prompt_text = (
        "You lead a maintenance reliability team at Meridian Heavy Industries. A reliability "
        "engineer has asked for a repair job assessment on one machine. Decide what the "
        "specialist team should concentrate on and in what order they should check it.\n\n"
        "You are given only the machine's register record. Do not diagnose anything, do not "
        "invent condition readings, and do not estimate risk or priority; the specialists and "
        "the plant's models do that.\n\n"
        "Machine register record:\n" + _facts_block(register_facts) + "\n\n"
        "Engineer's request: " + request_text + "\n\n"
        + FORMAT_RULES + "\n" + _labelled_template(PLANNER_FIELDS)
    )
    reply = call_language_model(prompt_text, config.AGENT_NAME_PLANNER)
    result = _keyed(parse_labelled_response(reply["response_text"], PLANNER_FIELDS))
    result["call_record"] = reply["call_record"]
    return result


def condition_analyst_agent(machine_profile, risk_facts, investigation_plan):
    """Explain what this week's readings and the model's settled risk score mean."""
    condition_readings = {
        name: machine_profile.get(name)
        for name in ("machine_code", "machine_type", "power_rating_kw", "average_vibration",
                     "highest_vibration", "vibration_change_pct", "average_temperature_c",
                     "highest_temperature_c", "room_temperature_c", "oil_dirtiness_score",
                     "days_since_oil_check", "alarms_this_week", "days_since_last_service",
                     "breakdowns_last_year", "running_hours_per_week", "average_load_pct")
    }
    plan = {name: value for name, value in investigation_plan.items() if name != "call_record"}
    prompt_text = (
        "You are the condition analyst on a maintenance reliability team. Explain to a "
        "maintenance supervisor what this week's condition readings and the breakdown risk "
        "model's score mean for this machine.\n\n"
        "The breakdown probability and risk band below are settled facts produced by the "
        "plant's trained model. Do not recalculate, adjust or question them. Cite only the "
        "readings listed here; do not invent any.\n\n"
        "Team lead's brief (answer it):\n" + _facts_block(plan) + "\n\n"
        "Risk facts:\n" + _facts_block({
            "breakdown_probability": risk_facts["breakdown_probability"],
            "risk_band": risk_facts["risk_band"],
        }) + "\n\n"
        "This week's readings:\n" + _facts_block(condition_readings) + "\n\n"
        "URGENCY is one plain word for a human reader (for example Immediate, Soon or Routine). "
        "It is not the repair job priority, which is set separately by plant policy.\n\n"
        + FORMAT_RULES + "\n" + _labelled_template(CONDITION_FIELDS)
    )
    reply = call_language_model(prompt_text, config.AGENT_NAME_CONDITION)
    result = _keyed(parse_labelled_response(reply["response_text"], CONDITION_FIELDS))
    result["call_record"] = reply["call_record"]
    return result


def problem_analyst_agent(problem_facts, condition_assessment):
    """Weigh the note classifier's votes against the condition reading."""
    assessment = {name: value for name, value in condition_assessment.items() if name != "call_record"}
    prompt_text = (
        "You are the reliability engineer on a maintenance team. A trained classifier has read "
        "every past technician note for this machine and voted on the problem type each note "
        "describes. Judge what those votes mean and whether the condition data supports or "
        "contradicts them.\n\n"
        "Do not reclassify the notes yourself. LIKELY PROBLEM TYPE must be one of the problem "
        "types that appear in the vote count below, written exactly as it appears there. If "
        "there are no votes, write None.\n\n"
        "Classifier verdict on the note history:\n" + _facts_block(problem_facts) + "\n\n"
        "Condition analyst's reading:\n" + _facts_block(assessment) + "\n\n"
        + FORMAT_RULES + "\n" + _labelled_template(PROBLEM_FIELDS)
    )
    reply = call_language_model(prompt_text, config.AGENT_NAME_PROBLEM)
    result = _keyed(parse_labelled_response(reply["response_text"], PROBLEM_FIELDS))
    result["call_record"] = reply["call_record"]
    return result


def procedure_advisor_agent(procedure_facts, problem_analysis):
    """Turn the retrieved manual and safety passages into the procedure part of a repair job."""
    analysis = {name: value for name, value in problem_analysis.items() if name != "call_record"}
    prompt_text = (
        "You are the procedure specialist on a maintenance team. Using ONLY the manual passages "
        "below, state which procedure applies, the permit position, the parts named, the safety "
        "requirements, and the repair steps in order.\n\n"
        "Every detail must come from the passages. Where a detail is not in them, write "
        "'Not stated in the retrieved documents' rather than supplying it from general "
        "engineering knowledge. Quote procedure codes, part codes and torque values exactly.\n\n"
        "Reliability engineer's judgement:\n" + _facts_block(analysis) + "\n\n"
        "Repair procedure passages:\n" + procedure_facts["procedure_context"] + "\n\n"
        "Safety passages:\n" + procedure_facts["safety_context"] + "\n\n"
        + FORMAT_RULES + " List the steps under " + PROCEDURE_STEPS_LABEL + " as a numbered list, "
        "one step per line.\n" + _labelled_template(PROCEDURE_FIELDS, PROCEDURE_STEPS_LABEL)
    )
    reply = call_language_model(prompt_text, config.AGENT_NAME_PROCEDURE)
    result = _keyed(parse_labelled_response(reply["response_text"], PROCEDURE_FIELDS))
    result["key_steps"] = parse_numbered_steps(reply["response_text"], PROCEDURE_STEPS_LABEL)
    result["call_record"] = reply["call_record"]
    return result


def repair_job_writer_agent(condition_assessment, problem_analysis, procedure_guidance):
    """Write the draft a supervisor will read: summary, task steps and a scheduling note."""
    def without_call(record):
        return {name: value for name, value in record.items() if name != "call_record"}

    prompt_text = (
        "You write repair jobs for Meridian Heavy Industries. Write a DRAFT repair job that a "
        "maintenance supervisor must approve before any work starts.\n\n"
        "Use only the steps the procedure specialist provided; you may tidy their wording but "
        "must not add a step they did not give. Do not state or work out a risk number, a "
        "priority or a downtime estimate; those are set elsewhere. JOB SUMMARY is two sentences "
        "a supervisor can read at a glance. SCHEDULING NOTE says when the work should be done "
        "and why, in one line.\n\n"
        "Condition analyst:\n" + _facts_block(without_call(condition_assessment)) + "\n\n"
        "Reliability engineer:\n" + _facts_block(without_call(problem_analysis)) + "\n\n"
        "Procedure specialist:\n" + _facts_block(without_call(procedure_guidance)) + "\n\n"
        + FORMAT_RULES + " List the steps under " + WRITER_STEPS_LABEL + " as a numbered list, "
        "one step per line.\n" + _labelled_template(WRITER_FIELDS, WRITER_STEPS_LABEL, "JOB SUMMARY")
    )
    reply = call_language_model(prompt_text, config.AGENT_NAME_WRITER)
    result = _keyed(parse_labelled_response(reply["response_text"], WRITER_FIELDS))
    result["task_steps"] = parse_numbered_steps(reply["response_text"], WRITER_STEPS_LABEL)
    result["call_record"] = reply["call_record"]
    return result


def repair_job_finalizer_agent(draft_repair_job, review_decision):
    """Rewrite the draft to carry out exactly what the supervisor decided, and say what changed."""
    draft_view = {
        name: draft_repair_job.get(name)
        for name in ("job_summary", "task_steps", "scheduling_note", "proposed_window")
    }
    prompt_text = (
        "You finalise repair jobs after a maintenance supervisor's review. Rewrite the draft so "
        "it carries out exactly what the supervisor decided.\n\n"
        "Apply the supervisor's instruction exactly: add no work they did not ask for and drop "
        "nothing they did not ask to remove. If the instruction asks for no change, keep the "
        "summary and steps as they are and write 'No changes' under CHANGES APPLIED.\n\n"
        "Draft repair job:\n" + _facts_block(draft_view) + "\n\n"
        "Supervisor's decision:\n" + _facts_block({
            "decision": review_decision.get("decision"),
            "reviewer_name": review_decision.get("reviewer_name"),
            "feedback_text": review_decision.get("feedback_text"),
        }) + "\n\n"
        + FORMAT_RULES + " List the steps under " + FINALIZER_STEPS_LABEL + " as a numbered list, "
        "one step per line.\n" + _labelled_template(FINALIZER_FIELDS, FINALIZER_STEPS_LABEL, "FINAL SUMMARY")
    )
    reply = call_language_model(prompt_text, config.AGENT_NAME_FINALIZER)
    result = _keyed(parse_labelled_response(reply["response_text"], FINALIZER_FIELDS))
    result["task_steps"] = parse_numbered_steps(reply["response_text"], FINALIZER_STEPS_LABEL)
    result["call_record"] = reply["call_record"]
    return result
__ASSETGUARD_EOF__

# ---- agentic/graph.py
mkdir -p "agentic"
cat > 'agentic/graph.py' <<'__ASSETGUARD_EOF__'
"""Wires the nine steps into one workflow that saves itself to disk after every step."""

import sqlite3

from langgraph.checkpoint.sqlite import SqliteSaver
from langgraph.graph import END, START, StateGraph
from langgraph.types import Command

from agentic import nodes
from agentic.state import RepairAdvisoryState
from config import config

STEP_ORDER = [
    ("load_machine_context", nodes.load_machine_context_node),
    ("plan_investigation", nodes.plan_investigation_node),
    ("assess_machine_condition", nodes.assess_machine_condition_node),
    ("identify_problem_type", nodes.identify_problem_type_node),
    ("retrieve_procedure", nodes.retrieve_procedure_node),
    ("compose_repair_job", nodes.compose_repair_job_node),
    ("request_supervisor_review", nodes.request_supervisor_review_node),
    ("finalize_repair_job", nodes.finalize_repair_job_node),
    ("persist_review_outcome", nodes.persist_review_outcome_node),
]


def create_checkpoint_saver(checkpoint_path):
    """An on-disk store for paused runs, usable from the API's worker threads."""
    connection = sqlite3.connect(checkpoint_path, check_same_thread=False)
    return SqliteSaver(connection)


def route_after_review(state):
    """REJECT skips the finalizer; any other decision goes through it."""
    if state["review_decision"]["decision"] == config.REVIEW_DECISION_REJECT:
        return "persist_review_outcome"
    return "finalize_repair_job"


def build_workflow(checkpoint_saver):
    """Register the steps in order, branch after review, and bind the checkpoint store."""
    workflow = StateGraph(RepairAdvisoryState)
    for step_name, step_function in STEP_ORDER:
        workflow.add_node(step_name, step_function)

    workflow.add_edge(START, "load_machine_context")
    linear_steps = [name for name, _ in STEP_ORDER[:7]]
    for current_step, next_step in zip(linear_steps, linear_steps[1:]):
        workflow.add_edge(current_step, next_step)
    # Both destinations are declared on the branch so the drawn graph shows them.
    workflow.add_conditional_edges(
        "request_supervisor_review",
        route_after_review,
        {"finalize_repair_job": "finalize_repair_job", "persist_review_outcome": "persist_review_outcome"},
    )
    workflow.add_edge("finalize_repair_job", "persist_review_outcome")
    workflow.add_edge("persist_review_outcome", END)
    return workflow.compile(checkpointer=checkpoint_saver)


def build_initial_state(advisory_request, thread_id):
    """Every declared key, empty except the request fields and thread_id."""
    return {
        "machine_code": advisory_request["machine_code"],
        "request_text": advisory_request["request_text"],
        "access_level": advisory_request["access_level"],
        "thread_id": thread_id,
        "run_id": "",
        "machine_profile": {},
        "risk_facts": {},
        "problem_facts": {},
        "procedure_facts": {},
        "investigation_plan": {},
        "condition_assessment": {},
        "problem_analysis": {},
        "procedure_guidance": {},
        "draft_repair_job": {},
        "review_decision": {},
        "final_repair_job": {},
        "llm_call_log": [],
    }


def start_advisory_run(compiled_graph, initial_state, thread_config):
    """Run until the review gate pauses the workflow; return the state at the pause."""
    compiled_graph.invoke(initial_state, thread_config, durability="sync")
    return compiled_graph.get_state(thread_config).values


def resume_workflow_after_review(compiled_graph, thread_config, review_decision):
    """Feed the supervisor's answer to the paused gate and run to the end."""
    compiled_graph.invoke(Command(resume=review_decision), thread_config, durability="sync")
    return compiled_graph.get_state(thread_config).values
__ASSETGUARD_EOF__

# ---- agentic/nodes.py
mkdir -p "agentic"
cat > 'agentic/nodes.py' <<'__ASSETGUARD_EOF__'
"""The nine steps of the advisory run.

Each step reads the shared state, does one piece of work, and returns only the
keys it changed. Tool work happens here, in plain code; agents only interpret.
Everything slow to load is loaded once, when this module is imported.
"""

import uuid

from langgraph.types import interrupt

from agentic.agents import (
    condition_analyst_agent,
    problem_analyst_agent,
    procedure_advisor_agent,
    repair_job_finalizer_agent,
    repair_job_writer_agent,
    work_planner_agent,
)
from config import config
from data_pipeline.dataset_loader import load_processed_dataset
from modeling.model_registry import load_feature_schema, load_model_artifact
from persistence.database import open_database_session
from persistence.repository import (
    apply_review_outcome,
    insert_agent_run,
    insert_llm_call_record,
    insert_repair_job_draft,
    insert_review_decision,
    update_agent_run_status,
    update_repair_job_status,
)
from tools.machine_data_tools import fetch_machine_note_history, fetch_machine_profile, load_current_fleet
from tools.prediction_tools import (
    apply_tight_space_factor,
    build_model_input_row,
    build_planned_repair_record,
    classify_risk_band,
    detect_problem_type,
    estimate_repair_downtime,
    predict_breakdown_probability,
    resolve_repair_priority,
)
from tools.retrieval_tools import lookup_repair_procedure, lookup_safety_requirement, open_manual_search

BREAKDOWN_MODEL = load_model_artifact(config.BREAKDOWN_MODEL_FILE)
BREAKDOWN_SCHEMA = load_feature_schema(config.BREAKDOWN_SCHEMA_FILE)
DOWNTIME_MODEL = load_model_artifact(config.DOWNTIME_MODEL_FILE)
DOWNTIME_SCHEMA = load_feature_schema(config.DOWNTIME_SCHEMA_FILE)
PROBLEM_TYPE_MODEL = load_model_artifact(config.PROBLEM_TYPE_MODEL_FILE)
TEXT_VECTORIZER = load_model_artifact(config.TEXT_VECTORIZER_FILE)
CURRENT_FLEET = load_current_fleet(config.CURRENT_FLEET_FILE)
TECHNICIAN_NOTES = load_processed_dataset(config.CLEAN_TECHNICIAN_NOTES_FILE)
MANUAL_SEARCH = open_manual_search(config.VECTOR_STORE_DIRECTORY, config.VECTOR_COLLECTION_NAME)

RISK_THRESHOLDS = {"high": config.HIGH_RISK_THRESHOLD, "medium": config.MEDIUM_RISK_THRESHOLD}


def _record_call(run_id, call_record):
    """Write one spent call to the database straight away, in its own session."""
    session = open_database_session()
    try:
        insert_llm_call_record(session, call_record, run_id)
    finally:
        session.close()


def _agent_output(agent_result):
    """The agent's fields without the call measurement, which goes to the log instead."""
    return {name: value for name, value in agent_result.items() if name != "call_record"}


def load_machine_context_node(state):
    machine_profile = fetch_machine_profile(CURRENT_FLEET, state["machine_code"])
    if not machine_profile:
        raise LookupError("Machine " + state["machine_code"] + " is not in the current fleet")

    run_id = "RUN-" + uuid.uuid4().hex[:12].upper()
    session = open_database_session()
    try:
        insert_agent_run(session, {
            "run_id": run_id,
            "thread_id": state["thread_id"],
            "machine_code": state["machine_code"],
            "request_text": state["request_text"],
            "status": config.AGENT_RUN_STATUS_RUNNING,
        })
    finally:
        session.close()
    return {"run_id": run_id, "machine_profile": machine_profile}


def plan_investigation_node(state):
    result = work_planner_agent(state["machine_profile"], state["request_text"])
    _record_call(state["run_id"], result["call_record"])
    return {"investigation_plan": _agent_output(result), "llm_call_log": [result["call_record"]]}


def assess_machine_condition_node(state):
    machine_profile = state["machine_profile"]
    feature_row = build_model_input_row(machine_profile, BREAKDOWN_SCHEMA)
    probability = predict_breakdown_probability(BREAKDOWN_MODEL, feature_row)
    risk_band = classify_risk_band(probability, RISK_THRESHOLDS)
    risk_facts = {
        "breakdown_probability": probability,
        "risk_band": risk_band,
        "priority": resolve_repair_priority(machine_profile["importance"], risk_band),
    }

    result = condition_analyst_agent(machine_profile, risk_facts, state["investigation_plan"])
    _record_call(state["run_id"], result["call_record"])
    return {
        "risk_facts": risk_facts,
        "condition_assessment": _agent_output(result),
        "llm_call_log": [result["call_record"]],
    }


def identify_problem_type_node(state):
    note_history = fetch_machine_note_history(TECHNICIAN_NOTES, state["machine_code"])
    problem_facts = detect_problem_type(PROBLEM_TYPE_MODEL, TEXT_VECTORIZER, note_history)

    result = problem_analyst_agent(problem_facts, state["condition_assessment"])
    _record_call(state["run_id"], result["call_record"])
    return {
        "problem_facts": problem_facts,
        "problem_analysis": _agent_output(result),
        "llm_call_log": [result["call_record"]],
    }


def retrieve_procedure_node(state):
    machine_type = state["machine_profile"]["machine_type"]
    procedure = lookup_repair_procedure(MANUAL_SEARCH, machine_type, state["problem_facts"]["problem_type"])
    safety = lookup_safety_requirement(MANUAL_SEARCH, machine_type)

    source_documents = []
    for document_name in procedure["source_documents"] + safety["source_documents"]:
        if document_name not in source_documents:
            source_documents.append(document_name)
    procedure_facts = {
        "procedure_context": procedure["context_text"],
        "safety_context": safety["context_text"],
        "source_documents": source_documents,
    }

    result = procedure_advisor_agent(procedure_facts, state["problem_analysis"])
    _record_call(state["run_id"], result["call_record"])
    return {
        "procedure_facts": procedure_facts,
        "procedure_guidance": _agent_output(result),
        "llm_call_log": [result["call_record"]],
    }


def compose_repair_job_node(state):
    risk_facts = state["risk_facts"]
    problem_type = state["problem_facts"]["problem_type"]
    guidance = state["procedure_guidance"]

    # The downtime model is asked to assume the baseline access level; the
    # Safety Rule 03 tight space stretch is then applied once, by the rule.
    planned_record = build_planned_repair_record(
        state["machine_profile"], risk_facts,
        {"problem_type": problem_type, "access_level": config.ACCESS_LEVEL_BASELINE},
    )
    model_hours = estimate_repair_downtime(DOWNTIME_MODEL, build_model_input_row(planned_record, DOWNTIME_SCHEMA))
    estimated_downtime_hours = apply_tight_space_factor(model_hours, state["access_level"])

    result = repair_job_writer_agent(state["condition_assessment"], state["problem_analysis"], guidance)
    _record_call(state["run_id"], result["call_record"])

    draft_repair_job = {
        "repair_job_id": "WO-" + uuid.uuid4().hex[:10].upper(),
        "run_id": state["run_id"],
        "machine_code": state["machine_code"],
        "machine_type": state["machine_profile"]["machine_type"],
        "breakdown_probability": risk_facts["breakdown_probability"],
        "risk_band": risk_facts["risk_band"],
        "problem_type": problem_type,
        "priority": risk_facts["priority"],
        "estimated_downtime_hours": estimated_downtime_hours,
        "permit_required": guidance.get("permit_required", ""),
        "procedure_reference": guidance.get("procedure_reference", ""),
        "parts_required": guidance.get("parts_required", ""),
        "task_steps": "\n".join(result["task_steps"]),
        "safety_notes": guidance.get("safety_notes", ""),
        "proposed_window": config.STANDARD_SHUTDOWN_WINDOW,
        "source_documents": ", ".join(state["procedure_facts"]["source_documents"]),
        "job_summary": result.get("job_summary", ""),
        "scheduling_note": result.get("scheduling_note", ""),
        "status": config.REPAIR_JOB_STATUS_PENDING,
    }

    session = open_database_session()
    try:
        insert_repair_job_draft(session, draft_repair_job)
        update_agent_run_status(session, state["run_id"], config.AGENT_RUN_STATUS_AWAITING_REVIEW)
    finally:
        session.close()
    return {"draft_repair_job": draft_repair_job, "llm_call_log": [result["call_record"]]}


def request_supervisor_review_node(state):
    """The human gate. interrupt() saves the run to disk and stops until a supervisor answers."""
    draft = state["draft_repair_job"]
    review_summary = {name: draft[name] for name in (
        "repair_job_id", "machine_code", "risk_band", "priority",
        "estimated_downtime_hours", "job_summary", "task_steps", "proposed_window")}
    review_summary["decision_options"] = config.REVIEW_DECISION_OPTIONS
    review_decision = interrupt(review_summary)
    return {"review_decision": dict(review_decision)}


def finalize_repair_job_node(state):
    draft = state["draft_repair_job"]
    result = repair_job_finalizer_agent(draft, state["review_decision"])
    _record_call(state["run_id"], result["call_record"])

    final_repair_job = dict(draft)
    # If the model's reply could not be read, keep the draft wording rather than
    # wiping it: nothing the supervisor did not ask to change may be dropped.
    final_repair_job["job_summary"] = result.get("final_summary") or draft["job_summary"]
    final_repair_job["task_steps"] = "\n".join(result["task_steps"]) if result["task_steps"] else draft["task_steps"]
    final_repair_job["changes_applied"] = result.get("changes_applied") or "No changes"
    final_repair_job["status"] = config.REPAIR_JOB_STATUS_APPROVED
    return {"final_repair_job": final_repair_job, "llm_call_log": [result["call_record"]]}


def persist_review_outcome_node(state):
    draft = state["draft_repair_job"]
    decision = state["review_decision"]
    session = open_database_session()
    try:
        insert_review_decision(session, {
            "run_id": state["run_id"],
            "repair_job_id": draft["repair_job_id"],
            "decision": decision["decision"],
            "reviewer_name": decision["reviewer_name"],
            "feedback_text": decision["feedback_text"],
            # What the supervisor actually saw, kept before the finalizer's version replaces it.
            "reviewed_draft": "JOB SUMMARY:\n" + draft["job_summary"] + "\n\nTASK STEPS:\n" + draft["task_steps"],
        })
        if decision["decision"] == config.REVIEW_DECISION_REJECT:
            update_repair_job_status(session, draft["repair_job_id"], config.REPAIR_JOB_STATUS_REJECTED)
        else:
            apply_review_outcome(session, draft["repair_job_id"], state["final_repair_job"])
        update_agent_run_status(session, state["run_id"], config.AGENT_RUN_STATUS_COMPLETE)
    finally:
        session.close()
    return {}
__ASSETGUARD_EOF__

# ---- agentic/state.py
mkdir -p "agentic"
cat > 'agentic/state.py' <<'__ASSETGUARD_EOF__'
"""The single state dictionary every workflow step reads and writes.

This is also exactly what is written to disk at the review pause, so it defines
what a resumed run remembers.
"""

import operator
from typing import Annotated, TypedDict


class RepairAdvisoryState(TypedDict):
    machine_code: str
    request_text: str
    access_level: str
    thread_id: str
    run_id: str
    machine_profile: dict
    risk_facts: dict
    problem_facts: dict
    procedure_facts: dict
    investigation_plan: dict
    condition_assessment: dict
    problem_analysis: dict
    procedure_guidance: dict
    draft_repair_job: dict
    review_decision: dict
    final_repair_job: dict
    # Each step returns a one-entry list; operator.add appends it to the log
    # instead of replacing the log.
    llm_call_log: Annotated[list, operator.add]
__ASSETGUARD_EOF__

# ---- api/routes.py
mkdir -p "api"
cat > 'api/routes.py' <<'__ASSETGUARD_EOF__'
"""The AssetGuard AI REST service.

The only place in the running system where models are loaded and risk is
scored. Sign in and sign out stand outside the guard; every other endpoint sits
behind it: first the caller is identified from their token, then their role is
checked against the area the requested path belongs to.
"""

import uuid
from typing import Annotated

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Query, Request, status
from fastapi.responses import JSONResponse
from google.genai import errors as genai_errors
from sqlalchemy.orm import Session

from access.password_security import create_session_token, verify_password_matches
from access.permissions import check_role_may_open_area, resolve_area_for_path, resolve_pages_for_role
from agentic import nodes
from agentic.graph import (
    build_initial_state,
    build_workflow,
    create_checkpoint_saver,
    resume_workflow_after_review,
    start_advisory_run,
)
from api.schemas import (
    AdvisoryRequest,
    CallBudgetResponse,
    ChatRequest,
    ChatResponse,
    ChatTurnResponse,
    FleetRiskRow,
    MachineNoteHistoryResponse,
    MachineProfileResponse,
    RepairJobResponse,
    ReviewDecisionRequest,
    ReviewDecisionResponse,
    RiskAssessmentResponse,
    SignedInUserResponse,
    SignInRequest,
    SignOutResponse,
)
from chat.conversation_memory import build_search_text, format_history_for_prompt, trim_conversation_history
from chat.machine_status_answer import build_machine_status_answer, build_unknown_machine_answer
from chat.manual_assistant import (
    LABEL_ANSWER,
    LABEL_MACHINE_ID,
    LABEL_QUESTION_TYPE,
    NONE_VALUE,
    answer_manual_question,
    check_answer_is_grounded,
    retrieve_manual_context,
)
from config import config
from persistence import repository
from persistence.database import create_database_directory, get_database_session
from tools.machine_data_tools import fetch_machine_note_history, fetch_machine_profile
from tools.prediction_tools import (
    build_model_input_row,
    classify_risk_band,
    detect_problem_type,
    predict_breakdown_probability,
    resolve_repair_priority,
    score_current_fleet,
)

# Prepared once at start-up. The models, fleet and notes are the ones the
# workflow steps already loaded, so the 130 MB risk model is held only once.
create_database_directory(config.DATABASE_DIRECTORY)
WORKFLOW = build_workflow(create_checkpoint_saver(config.CHECKPOINT_DATABASE_FILE))
SCORED_FLEET = score_current_fleet(nodes.BREAKDOWN_MODEL, nodes.CURRENT_FLEET, nodes.BREAKDOWN_SCHEMA)
RISK_THRESHOLDS = {"high": config.HIGH_RISK_THRESHOLD, "medium": config.MEDIUM_RISK_THRESHOLD}
FLEET_BAND_OPTIONS = [config.RISK_BAND_HIGH, config.RISK_BAND_MEDIUM, config.RISK_BAND_LOW, config.RISK_BAND_ALL]
RECENT_NOTE_COUNT = 5

DatabaseSession = Annotated[Session, Depends(get_database_session)]
SessionTokenHeader = Annotated[str, Header(alias=config.SESSION_TOKEN_HEADER)]


def _thread_config(thread_id):
    return {"configurable": {"thread_id": thread_id}}


def _machine_profile_or_404(machine_code):
    machine_profile = fetch_machine_profile(nodes.CURRENT_FLEET, machine_code)
    if not machine_profile:
        raise HTTPException(status.HTTP_404_NOT_FOUND, "Machine " + machine_code + " was not found")
    return machine_profile


def _repair_job_or_404(session, repair_job_id):
    repair_job = repository.fetch_repair_job_by_id(session, repair_job_id)
    if not repair_job:
        raise HTTPException(status.HTTP_404_NOT_FOUND, "Repair job " + repair_job_id + " was not found")
    return repair_job


# ---------------------------------------------------------------- sign in and the guard

def sign_in_user(sign_in_request: SignInRequest, session: DatabaseSession):
    account = repository.fetch_user_by_username(session, sign_in_request.username)
    # An unknown username and a wrong password get the same answer, so a stranger
    # cannot learn which accounts exist.
    if not account or not verify_password_matches(
            sign_in_request.password, account["password_hash"], account["password_salt"]):
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, config.SIGN_IN_FAILED_MESSAGE)

    session_token = create_session_token()
    repository.update_user_session_token(session, account["username"], session_token)
    return {
        "username": account["username"],
        "display_name": account["display_name"],
        "role": account["role"],
        "session_token": session_token,
        "allowed_pages": resolve_pages_for_role(account["role"]),
    }


def sign_out_user(session: DatabaseSession, x_session_token: SessionTokenHeader):
    account = repository.fetch_user_by_session_token(session, x_session_token)
    if account:
        repository.update_user_session_token(session, account["username"], "")
    # The same answer whether or not the token was live.
    return {"signed_out": True}


def resolve_signed_in_user(session: DatabaseSession, x_session_token: SessionTokenHeader):
    account = repository.fetch_user_by_session_token(session, x_session_token)
    if not account:
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "Sign in first: this session token is not recognised")
    return account


def require_area_access(request: Request, signed_in_user: Annotated[dict, Depends(resolve_signed_in_user)]):
    area_name = resolve_area_for_path(request.url.path, request.method)
    if not check_role_may_open_area(signed_in_user["role"], area_name):
        raise HTTPException(
            status.HTTP_403_FORBIDDEN,
            "Role " + signed_in_user["role"] + " may not open the " + (area_name or "unknown") + " area",
        )
    return signed_in_user


# ---------------------------------------------------------------- machines and fleet

def get_machine_profile(machine_code: str):
    return _machine_profile_or_404(machine_code)


def _score_machine(machine_profile):
    probability = predict_breakdown_probability(
        nodes.BREAKDOWN_MODEL, build_model_input_row(machine_profile, nodes.BREAKDOWN_SCHEMA))
    risk_band = classify_risk_band(probability, RISK_THRESHOLDS)
    return {
        "machine_code": machine_profile["machine_code"],
        "breakdown_probability": probability,
        "risk_band": risk_band,
        "priority": resolve_repair_priority(machine_profile["importance"], risk_band),
        "importance": machine_profile["importance"],
    }


def get_machine_risk(machine_code: str):
    return _score_machine(_machine_profile_or_404(machine_code))


def list_fleet_risk_summary(risk_band: Annotated[str, Query()]):
    if risk_band not in FLEET_BAND_OPTIONS:
        raise HTTPException(
            status.HTTP_422_UNPROCESSABLE_CONTENT, "risk_band must be one of " + str(FLEET_BAND_OPTIONS))
    rows = SCORED_FLEET
    if risk_band != config.RISK_BAND_ALL:
        rows = rows[rows["risk_band"] == risk_band]
    return rows.to_dict(orient="records")


def get_machine_note_history(machine_code: str):
    note_history = fetch_machine_note_history(nodes.TECHNICIAN_NOTES, machine_code)
    problem_facts = detect_problem_type(nodes.PROBLEM_TYPE_MODEL, nodes.TEXT_VECTORIZER, note_history)
    return {
        "machine_code": machine_code,
        "note_count": problem_facts["note_count"],
        "detected_problem_type": problem_facts["problem_type"],
        "confidence": problem_facts["confidence"],
        "problem_votes": problem_facts["problem_votes"],
        "recent_notes": note_history[-RECENT_NOTE_COUNT:],
    }


# ---------------------------------------------------------------- advisory workflow

def create_advisory_run(advisory_request: AdvisoryRequest, session: DatabaseSession):
    # An unknown machine is refused before the workflow spends any model call.
    _machine_profile_or_404(advisory_request.machine_code)
    thread_id = "thread-" + uuid.uuid4().hex
    initial_state = build_initial_state(advisory_request.model_dump(), thread_id)
    paused_state = start_advisory_run(WORKFLOW, initial_state, _thread_config(thread_id))

    draft = paused_state.get("draft_repair_job") or {}
    if not draft.get("repair_job_id"):
        raise HTTPException(status.HTTP_500_INTERNAL_SERVER_ERROR, "The advisory run finished without a draft")
    return repository.fetch_repair_job_by_id(session, draft["repair_job_id"])


def list_repair_jobs_by_status(status_value: Annotated[str, Query()], session: DatabaseSession):
    if status_value not in config.REPAIR_JOB_STATUS_OPTIONS:
        raise HTTPException(
            status.HTTP_422_UNPROCESSABLE_CONTENT,
            "status_value must be one of " + str(config.REPAIR_JOB_STATUS_OPTIONS))
    return repository.fetch_repair_jobs_by_status(session, status_value)


def get_repair_job_detail(repair_job_id: str, session: DatabaseSession):
    return _repair_job_or_404(session, repair_job_id)


def submit_review_decision(repair_job_id: str, decision_request: ReviewDecisionRequest, session: DatabaseSession):
    repair_job = _repair_job_or_404(session, repair_job_id)
    agent_run = repository.fetch_agent_run(session, repair_job["run_id"])
    if not agent_run:
        raise HTTPException(status.HTTP_404_NOT_FOUND, "The run behind repair job " + repair_job_id + " was not found")
    if repair_job["status"] != config.REPAIR_JOB_STATUS_PENDING:
        raise HTTPException(
            status.HTTP_409_CONFLICT, "Repair job " + repair_job_id + " has already been decided: " + repair_job["status"])

    resume_workflow_after_review(WORKFLOW, _thread_config(agent_run["thread_id"]), decision_request.model_dump())
    # The workflow wrote through its own sessions, so read the final row fresh.
    session.expire_all()
    return repository.fetch_repair_job_by_id(session, repair_job_id)


def get_review_history(repair_job_id: str, session: DatabaseSession):
    repair_job = _repair_job_or_404(session, repair_job_id)
    return repository.fetch_decisions_for_run(session, repair_job["run_id"])


def get_call_budget(run_id: str, session: DatabaseSession):
    if not repository.fetch_agent_run(session, run_id):
        raise HTTPException(status.HTTP_404_NOT_FOUND, "Run " + run_id + " was not found")
    calls = repository.fetch_call_records_for_run(session, run_id)
    decisions = repository.fetch_decisions_for_run(session, run_id)
    rejected = any(decision["decision"] == config.REVIEW_DECISION_REJECT for decision in decisions)
    return {
        "run_id": run_id,
        "call_count": len(calls),
        "expected_call_count": config.EXPECTED_LLM_CALLS_PER_RUN - (1 if rejected else 0),
        "total_latency_milliseconds": sum(call["latency_milliseconds"] for call in calls),
        "calls": calls,
    }


# ---------------------------------------------------------------- manual chat

def ask_manual_assistant(
        chat_request: ChatRequest,
        signed_in_user: Annotated[dict, Depends(resolve_signed_in_user)],
        session: DatabaseSession):
    history = trim_conversation_history(
        [{"question": turn.question, "answer": turn.answer} for turn in chat_request.history],
        config.CHAT_HISTORY_TURN_LIMIT,
    )
    manual_context = retrieve_manual_context(nodes.MANUAL_SEARCH, build_search_text(history, chat_request.question))
    reply = answer_manual_question(chat_request.question, format_history_for_prompt(history), manual_context)

    question_type = reply[LABEL_QUESTION_TYPE].strip().upper()
    if question_type not in config.CHAT_TYPE_OPTIONS:
        question_type = config.CHAT_TYPE_OUT_OF_SCOPE
    machine_code = reply[LABEL_MACHINE_ID].strip()
    if machine_code.upper() == NONE_VALUE:
        machine_code = ""

    if question_type == config.CHAT_TYPE_MACHINE_STATUS:
        # A fact from the fleet data and the risk model, never from the manuals.
        source_documents = []
        machine_profile = fetch_machine_profile(nodes.CURRENT_FLEET, machine_code) if machine_code else {}
        if machine_profile:
            answer = build_machine_status_answer(machine_profile, _score_machine(machine_profile))
        else:
            answer = build_unknown_machine_answer(machine_code)
    elif (question_type == config.CHAT_TYPE_OUT_OF_SCOPE
          or not check_answer_is_grounded(question_type, manual_context["closest_distance"])
          or not reply[LABEL_ANSWER]):
        question_type = config.CHAT_TYPE_OUT_OF_SCOPE
        answer = config.CHAT_REFUSAL_MESSAGE
        source_documents = []
        machine_code = ""
    else:
        answer = reply[LABEL_ANSWER]
        source_documents = manual_context["source_documents"]

    repository.insert_chat_turn(session, {
        "username": signed_in_user["username"],
        "question": chat_request.question,
        "question_type": question_type,
        "answer": answer,
        "source_documents": ", ".join(source_documents),
        "machine_code": machine_code,
        "latency_milliseconds": reply["call_record"]["latency_milliseconds"],
    })
    return {
        "question_type": question_type,
        "answer": answer,
        "source_documents": source_documents,
        "chunks_searched": manual_context["chunk_count"],
    }


def list_recent_chat_turns(turn_limit: Annotated[int, Query()], session: DatabaseSession):
    if turn_limit < 1 or turn_limit > config.CHAT_AUDIT_MAX_ROWS:
        raise HTTPException(
            status.HTTP_422_UNPROCESSABLE_CONTENT,
            "turn_limit must be between 1 and " + str(config.CHAT_AUDIT_MAX_ROWS))
    return repository.fetch_recent_chat_turns(session, turn_limit)


# ---------------------------------------------------------------- application

def create_api_application(application_title):
    """Attach every endpoint to a new application. Does not start a server."""
    application = FastAPI(
        title=application_title,
        description="Predictive maintenance and repair job advisory service for Meridian Heavy Industries.",
    )

    open_routes = APIRouter()
    open_routes.add_api_route("/auth/signin", sign_in_user, methods=["POST"], response_model=SignedInUserResponse)
    open_routes.add_api_route("/auth/signout", sign_out_user, methods=["POST"], response_model=SignOutResponse)

    guarded = APIRouter(dependencies=[Depends(require_area_access)])
    guarded.add_api_route("/machines/{machine_code}", get_machine_profile,
                          methods=["GET"], response_model=MachineProfileResponse)
    guarded.add_api_route("/machines/{machine_code}/risk", get_machine_risk,
                          methods=["GET"], response_model=RiskAssessmentResponse)
    guarded.add_api_route("/machines/{machine_code}/notes", get_machine_note_history,
                          methods=["GET"], response_model=MachineNoteHistoryResponse)
    guarded.add_api_route("/fleet/risk", list_fleet_risk_summary,
                          methods=["GET"], response_model=list[FleetRiskRow])
    guarded.add_api_route("/advisories", create_advisory_run, methods=["POST"],
                          response_model=RepairJobResponse, status_code=status.HTTP_201_CREATED)
    guarded.add_api_route("/repairjobs", list_repair_jobs_by_status,
                          methods=["GET"], response_model=list[RepairJobResponse])
    guarded.add_api_route("/repairjobs/{repair_job_id}", get_repair_job_detail,
                          methods=["GET"], response_model=RepairJobResponse)
    guarded.add_api_route("/repairjobs/{repair_job_id}/review", submit_review_decision,
                          methods=["POST"], response_model=RepairJobResponse)
    guarded.add_api_route("/repairjobs/{repair_job_id}/reviews", get_review_history,
                          methods=["GET"], response_model=list[ReviewDecisionResponse])
    guarded.add_api_route("/runs/{run_id}/calls", get_call_budget,
                          methods=["GET"], response_model=CallBudgetResponse)
    guarded.add_api_route("/chat/ask", ask_manual_assistant, methods=["POST"], response_model=ChatResponse)
    guarded.add_api_route("/audit/chat-turns", list_recent_chat_turns,
                          methods=["GET"], response_model=list[ChatTurnResponse])

    application.include_router(open_routes)
    application.include_router(guarded)
    application.add_exception_handler(genai_errors.APIError, _language_model_unavailable)
    return application


def _language_model_unavailable(request: Request, model_error: genai_errors.APIError):
    # The service is up but the model provider is not; say so rather than a bare 500.
    return JSONResponse(
        status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
        content={"detail": "The language model did not answer (" + str(model_error.code)
                           + "). Try again in a minute."},
    )
__ASSETGUARD_EOF__

